// ── Send TELEX with chunking ──
// Hoppie only supports ASCII — strip accents/ñ before sending

async function sendTelex(to, body, { auto = true, key = null } = {}) { // 6.0: key = clave del mensaje generado (msgStatus/msgSentAt), si la tiene
  to = NBV.acars.to(to); // callsign ACARS si el piloto usa uno distinto al de IVAO
  try {
    await hoppieSendTelex(to, body);
    try { NBV.bus.emitRemote('sent', { to }); } catch (e) {}
    discordNotifyTelex(to, body, auto, true, key);
  } catch (e) {
    discordNotifyTelex(to, body, auto, false, key);
    throw e;
  }
  totalMsgsSent++;
  NBV.ui.stats.msg('tx');
  return true;
}

// ══════════════════════════════════════════════════════════════════
//  MESSAGE HISTORY & ANTI-DUPLICATION
// ══════════════════════════════════════════════════════════════════

const SENT_STORAGE_KEY = 'an_ops_sent_registry';
const HIST_STORAGE_KEY = 'an_ops_msg_history';
let sentRegistry = {};   // { "callsign_dep_arr_phase": timestamp }
let msgHistory = [];      // [{ time, callsign, phase, msgId, status, label }]

function loadSentRegistry() {
  try {
    const s = localStorage.getItem(SENT_STORAGE_KEY);
    if (s) sentRegistry = JSON.parse(s);
    const h = localStorage.getItem(HIST_STORAGE_KEY);
    if (h) msgHistory = JSON.parse(h);
    // Prune entries older than 6 hours
    const cutoff = Date.now() - 6 * 3600000;
    let pruned = 0;
    for (const k in sentRegistry) { if (sentRegistry[k] < cutoff) { delete sentRegistry[k]; pruned++; } }
    msgHistory = msgHistory.filter(m => m.ts > cutoff);
    saveSentRegistry();
    const keys = Object.keys(sentRegistry).length;
    if (keys > 0) log(`DEDUP: ${keys} registros cargados de sesion anterior (${pruned} expirados)`, 'ops');
  } catch(e) { sentRegistry = {}; msgHistory = []; log(`DEDUP: error cargando registros: ${e.message}`, 'err'); }
  renderMsgHistory();
}
// 5.5 (G2): otra ventana del OPS (la embebida en el ACARS, por ejemplo) pudo registrar envíos después de cargar esta: se fusionan (gana la hora más reciente)
function reloadSentRegistry() {
  try {
    const s = JSON.parse(localStorage.getItem(SENT_STORAGE_KEY) || '{}') || {}, cutoff = Date.now() - 6 * 3600000; // lo caducado no vuelve (poda de loadSentRegistry)
    for (const k in s) if (typeof s[k] === 'number' && s[k] > cutoff && !(sentRegistry[k] >= s[k])) sentRegistry[k] = s[k];
  } catch (e) { /* registro ilegible: se sigue con el de memoria */ }
}
// 5.5.2 (A6): dos ventanas del OPS (la embebida en el ACARS y otra) se pisaban el historial. Antes de guardar se relee y se fusiona
// por fila (ts|cs|key|label); ante duplicados gana el estado más avanzado. Como mucho 200 filas, las más recientes, y de las últimas 6 h.
const HIST_RANK = { delivered: 5, unpicked: 4, sent: 3, held: 2, error: 1, skip: 0 };
// Revisión del punto 4: «Limpiar» deja su hora en el registro compartido (HIST_CLEARED, sin clave nueva de almacenamiento; caduca a las 6 h
// como el resto) y la fusión descarta las filas anteriores: si no, la otra ventana resucitaba el historial borrado al guardar
const HIST_CLEARED = '~historial-limpiado';
function mergeMsgHistory(mine, stored) {
  // Las filas del mismo milisegundo que «Limpiar» son de después (se añaden tras vaciar): se conservan
  const by = new Map(), cutoff = Date.now() - 6 * 3600000, cleared = sentRegistry[HIST_CLEARED] || 0, rank = m => HIST_RANK[m.status] ?? -1;
  for (const m of [...mine, ...(Array.isArray(stored) ? stored : [])]) {
    if (!m || typeof m !== 'object' || !(m.ts > cutoff) || m.ts < cleared) continue;
    const id = `${m.ts}|${m.cs}|${m.key}|${m.label}`, cur = by.get(id);
    if (!cur || rank(m) > rank(cur)) by.set(id, m);
  }
  return [...by.values()].sort((a, b) => a.ts - b.ts).slice(-200);
}
function saveSentRegistry(merge = true) {
  try {
    if (merge) {
      reloadSentRegistry(); // la hora de «Limpiar» (y los envíos) de otra ventana
      let stored = []; try { stored = JSON.parse(localStorage.getItem(HIST_STORAGE_KEY) || '[]'); } catch (e) { /* historial ilegible: se sustituye por el de memoria */ }
      msgHistory = mergeMsgHistory(msgHistory, stored);
    }
    localStorage.setItem(SENT_STORAGE_KEY, JSON.stringify(sentRegistry));
    localStorage.setItem(HIST_STORAGE_KEY, JSON.stringify(msgHistory));
  } catch(e) {}
}

// Build dedup key: callsign + dep + arr + phase
// Use only callsign+phase as primary key when dep/arr unknown
function dedupKey(cs, dep, arr, phase) {
  const d = dep && dep !== '????' ? dep : '';
  const a = arr && arr !== '????' ? arr : '';
  return `${cs}_${d}_${a}_${phase}`.replace(/\s/g, '');
}

// Check if this message was already sent recently
function wasSentRecently(cs, dep, arr, phase, maxAgeMs) {
  const key = dedupKey(cs, dep, arr, phase);
  const t = sentRegistry[key];
  if (t && (Date.now() - t) < maxAgeMs) return true;
  // Also check callsign-only key (phase might have been recorded without route info)
  const fallbackKey = `${cs}___${phase}`;
  const t2 = sentRegistry[fallbackKey];
  if (t2 && (Date.now() - t2) < maxAgeMs) return true;
  return false;
}

// Record a sent message
function recordSent(cs, dep, arr, phase, msgLabel, status, msgBody, msgKey = '') {
  const key = dedupKey(cs, dep, arr, phase);
  // Revisión: la fila nunca es anterior a la marca de «Limpiar» (aunque el reloj no haya avanzado): así se distingue de las borradas
  reloadSentRegistry(); const ts = Math.max(Date.now(), sentRegistry[HIST_CLEARED] || 0);
  if (status === 'sent') {
    sentRegistry[key] = Date.now();
    // Store fallback key (cs+phase only) for restart dedup when dep/arr unknown
    sentRegistry[`${cs}___${phase}`] = Date.now();
    // Also store generic phase key for dedup (e.g. routeinfo_2 -> routeinfo)
    const generic = phase.replace(/_\d+$/, '');
    if (generic !== phase) {
      sentRegistry[dedupKey(cs, dep, arr, generic)] = Date.now();
      sentRegistry[`${cs}___${generic}`] = Date.now();
    }
    log(`DEDUP: registrado ${key}`, '');
  }
  msgHistory.push({ ts, cs, phase, label: msgLabel, status, body: msgBody || '', key: msgKey });
  if (msgHistory.length > 200) msgHistory = msgHistory.slice(-200);
  saveSentRegistry();
  renderMsgHistory();
}

// 5.5: cuando el avión recoge un mensaje enviado (Hoppie da la hora de recogida), su fila del historial pasa de «sent» a «delivered».
// Se busca por callsign y clave (fase_id) la fila más reciente aún en «sent»; las filas anteriores a la 5.5 no tienen clave y se quedan como están.
// Revisión del punto 4: tras reenviar un «sin recoger» hay dos filas de la misma clave; se marcan todas las que siguen en «sent» o «unpicked»
// hasta la última ya entregada (las de antes, de otra pierna con el mismo callsign, no se tocan)
function markHistoryDelivered(cs, key, relayed) {
  if (!key) return false;
  let n = 0;
  const legStart = flights[cs]?.firstSeen || 0; // segunda revisión: las filas de antes de la pierna en curso (otra pierna) no se tocan
  for (let i = msgHistory.length - 1; i >= 0; i--) {
    const m = msgHistory[i];
    if (m.cs !== cs || m.key !== key) continue;
    if (m.status === 'delivered' || m.ts < legStart) break;
    if (m.status === 'sent' || m.status === 'unpicked') { m.status = 'delivered'; m.relayed = String(relayed || ''); n++; }
  }
  if (n) { saveSentRegistry(); renderMsgHistory(); }
  return n > 0;
}

// 5.5.2 (A4): cambia el estado de la última fila de ese callsign y esa clave que siga en «sent» o «unpicked» (p. ej. a «unpicked»)
function markHistoryStatus(cs, key, status) {
  if (!key) return false;
  for (let i = msgHistory.length - 1; i >= 0; i--) {
    const m = msgHistory[i];
    if (m.cs === cs && m.key === key && (m.status === 'sent' || m.status === 'unpicked')) { m.status = status; saveSentRegistry(); renderMsgHistory(); return true; }
  }
  return false;
}

// ── History UI ──
function toggleMsgHistory() {
  $('mhBody').classList.toggle('open');
}
// Solo la tabla: el registro antiduplicado (sentRegistry) se conserva, o se reenviarían los mensajes de fase y los TELEX OOOI
// Hora más reciente de las filas en memoria y guardadas (la marca de «Limpiar» va siempre por delante de todas)
function histLastTs() {
  let st = []; try { st = JSON.parse(localStorage.getItem(HIST_STORAGE_KEY) || '[]'); } catch (e) { st = []; } // ilegible: solo las de memoria
  return [...msgHistory, ...(Array.isArray(st) ? st : [])].reduce((t, m) => Math.max(t, +m?.ts || 0), 0);
}
function clearMsgHistory() {
  const lastTs = histLastTs();
  reloadSentRegistry(); msgHistory = []; sentRegistry[HIST_CLEARED] = Date.now(); // segunda revisión: sin releer, guardar sin fusionar borraba los envíos de otra ventana
  sentRegistry[HIST_CLEARED] = Math.max(sentRegistry[HIST_CLEARED], lastTs + 1); // revisión: con el reloj quieto (mismo ms), las filas borradas quedan por detrás
  saveSentRegistry(false); // sin fusionar: vacía de verdad (5.5.2)
  renderMsgHistory();
}
function toggleMsgBody(idx) {
  const el = document.getElementById('mh-body-' + idx);
  if (!el) return;
  el.classList.toggle('open');
  // Rotate expand arrow in the parent row
  const arrow = el.previousElementSibling?.querySelector('.mh-expand');
  if (arrow) arrow.textContent = el.classList.contains('open') ? '▾' : '▸';
}
function renderMsgHistory() {
  const rows = $('mhRows');
  const empty = $('mhEmpty');
  $('mhCount').textContent = msgHistory.length;
  if (!msgHistory.length) {
    rows.innerHTML = '';
    empty.style.display = 'block';
    return;
  }
  empty.style.display = 'none';
  // Show newest first
  const sorted = [...msgHistory].reverse();
  rows.innerHTML = sorted.map((m, i) => {
    const t = new Date(m.ts).toISOString().substring(11,19);
    // 5.5.2 (A6): retenido y sin recoger tienen su etiqueta (ámbar), no «✗ ERROR»
    // 5.5.2 (P8): las respuestas a la autorización de rodaje (filas «TAXI CLR») tienen la suya: WILCO (verde) y UNABLE (ámbar)
    const stCls = ['delivered', 'sent', 'skip', 'held', 'unpicked', 'wilco', 'unable'].includes(m.status) ? m.status : 'error';
    const stLabel = m.status === 'delivered' ? `✓✓ RECIBIDO${m.relayed ? ' ' + m.relayed : ''}` : m.status === 'sent' ? '✓ ENVIADO' : m.status === 'skip' ? '⊘ OMITIDO'
      : m.status === 'held' ? '⏸ RETENIDO' : m.status === 'unpicked' ? '⚠ SIN RECOGER' : m.status === 'wilco' ? '✓ WILCO' : m.status === 'unable' ? '✗ UNABLE' : '✗ ERROR';
    const hasBody = m.body && m.body.trim().length > 0;
    const expandIconHtml = hasBody ? '<span class="mh-expand" title="Ver contenido">▸</span>' : '';
    const bodyRowHtml = hasBody ? `<tr id="mh-body-${Number(i)}" class="mh-body-row"><td colspan="5"><pre class="mh-body-pre">${esc(m.body)}</pre></td></tr>` : '';
    return `<tr class="${hasBody ? 'mh-clickable' : ''}" ${hasBody ? `data-click="toggleMsgBody|#${Number(i)}"` : ''}><td>${expandIconHtml}${esc(t)}</td><td>${esc(m.cs)}</td><td>${esc(m.phase)}</td><td>${esc(m.label)}</td><td><span class="mh-st ${esc(stCls)}">${esc(stLabel)}</span></td></tr>${bodyRowHtml}`;
  }).join('');
}



