  const tgt = cur.firstSeen === flt.firstSeen ? cur : flt; // si el callsign ya es otra pierna, el parking de esta no se le pasa
  opsAssignStand(tgt, await opsOsmFor(flt.arr)); // 5.5.2 (P1/P6): la misma puerta en todo el vuelo; OSM, como mucho 8 s
  let body = ri.body;
