// EET: estimateEnrouteMin pasa a NBV.opsLogic (src/core/10-ops-logica.js, v5)

// ══════════════════════════════════════════════════════════════════
//  MONITOR LOOP
// ══════════════════════════════════════════════════════════════════
let scanBusy = false;     // pasada en curso
let lastIvaoData = null;  // último whazzup (para el route info)

// 5.3.1: el simulador da datos recientes (<30 s) de este callsign → el avión sigue vivo aunque IVAO lo omita
function opsSimLive(cs) {
  const local = ($('fsuipcCs')?.value || '').trim().toUpperCase();
  return !!local && local === cs && !!fsuipcGetData(30000);
}

async function scan() {
  const prefix = $('cA').value.trim().toUpperCase();
  if (!prefix || scanBusy) return;
  scanBusy = true;
  try {
    const data = await NBV.ivao.get({ maxAge: 10000 });
    lastIvaoData = data;
    const allPilots = NBV.ivao.pilots(data);
    const nbvPilots = allPilots.filter(p => safeStr(p.callsign).toUpperCase().startsWith(prefix));
    if (nbvPilots.length) {
      log(`${prefix}: ${nbvPilots.length} detectado(s) [${nbvPilots.map(p => `${p.callsign}(${p.lastTrack?.onGround ? 'GND' : 'FL' + Math.round(safeNum(p.lastTrack?.altitude) / 100)} ${NBV.ivao.depOf(p) || '?'}-${NBV.ivao.arrOf(p) || '?'})`).join(', ')}]`, 'ops');
    } else {
      log(`${prefix}: ningún piloto detectado (${allPilots.length} en red)`, '');
    }

    const onlineCs = new Set(nbvPilots.map(p => p.callsign.toUpperCase()));
    await opsTechlogTick(Date.now()); // 5.2: estado técnico de tu avión (TechLog) antes de generar mensajes
    for (const ev of NBV.opsLogic.offline(flights, onlineCs, Date.now(), { simLive: opsSimLive })) { log(`${ev.cs} desconectado de IVAO`, 'wrn'); opsDispatchOffline(ev.cs, Date.now()); } // 6.0 (fase 2): alerta si estaba en el aire

    // v5: la decisión (estado, fase, qué enviar) está en NBV.opsLogic, sin DOM ni red; aquí solo se ejecuta
    const autoSend = $('cAuto').value === '1';
    for (const pilot of nbvPilots) {
      const cs = pilot.callsign.toUpperCase();
      const sim = opsSimLive(cs) ? fsuipcGetData() : null; // 5.3.1: velocidad vertical real de tu avión
      const { flt, events } = NBV.opsLogic.update(pilot, flights[cs] || null, { now: Date.now(), pv: phpvmsActive[cs], simVs: sim && typeof sim.verticalSpeed === 'number' ? sim.verticalSpeed : null });
      for (const ev of events) if (ev.type === 'newLeg') { log(`${cs}: nueva pierna ${ev.dep}→${ev.arr}`, 'ops'); opsCpdlcLogonClear(cs, flights[cs]); opsTaxiClrDrop(cs); } // 5.5.2 (P7): el LOGON de la pierna anterior ya no vale
      flights[cs] = flt;
      fsuipcInjectIntoFlight(flt);
      // 6.0 (fase 2): sin avisos sueltos de detectado ni de fase: un vuelo IVAO los lleva en su tarjeta (opsDispatchTick)
      for (const ev of events) {
        if (ev.type === 'detected') { log(`✈ ${cs} detectado: ${flt.dep}→${flt.arr} (${flt.aircraft})`, 'ops'); NBV.sound.play('detected'); }
        if (ev.type === 'phase') { log(`${cs}: ${ev.from} → ${ev.to}`, 'ops'); NBV.sound.play('phase'); }
      }
      opsRunActions(flt, pilot, autoSend);
      opsTaxiCheck(flt, [flt.lat, flt.lng], flt.gs).catch(e => log(`${cs}: autorización de rodaje: ${e.message}`, 'err')); // 5.5.2 (P6): sin esperar
    }
    opsCheckOwnCallsign(); // 5.5.2 (A5): FSUIPC conectado con «Mi callsign» que no es un vuelo del monitor

    await opsTrackDelivery().catch(() => {}); // 5.0 rc2: «esperando al avión» → «entregado HH:MMZ»
    await opsResendHeld().catch(() => {}); // 5.5.4: retenidos de llegada → se envían cuando el avión reaparece
    opsCheckUnpicked(Date.now()); // 5.5.2 (A4): llegada sin recoger en 3 min → «sin recoger», con reenvío en la tarjeta
    opsDispatchTick(Date.now(), onlineCs); // 5.1: registro de vuelos · 6.0 (fase 2): alertas de despacho y tarjeta de Discord
    await opsRegistroIntegraciones(Date.now()).catch(() => {}); // 5.2: TechLog del vuelo y comprobación de PIREP
    if ($('phpvmsEn')?.checked) phpvmsMergeWithFlights();
    opsTaxiSync(); // 5.5.2 (P6): estado de la autorización de rodaje (lo lleva el ACARS)
    updateDashboard(); updateStats(); updateAoc(); renderRosterChips(); flogRender();
    opsSaveState();
    const n = Object.values(flights).filter(f => !f.offlineSince).length;
    ss('live', `Monitor activo — ${n} vuelo(s) ${prefix} — ${tsShort()}`);
  } catch (e) {
    log(`Scan error: ${e.message}`, 'err');
    ss('err', `✗ ${e.message}`);
  } finally { scanBusy = false; }
}

// Acciones de NBV.opsLogic.decide() para un vuelo ya actualizado: las ejecuta scan() en cada pasada y, desde la 5.5.2 (A2),
// opsOooiSample() cuando el ON de FSUIPC da el aterrizaje de tu avión. flt._pilot guarda el último piloto de IVAO (no se persiste).
function opsRunActions(flt, pilot, autoSend) {
  const cs = flt.callsign;
  flt._pilot = pilot;
  for (const a of NBV.opsLogic.decide(flt, pilot, { riMode: $('cRI').value, hasGen: ph => !!PHASE_GEN[ph], wasSentRecently, now: Date.now() })) {
    if (a.type === 'eet') { if (a.min > 0) log(`${cs}: EET estimado ${Math.floor(a.min / 60)}h${String(a.min % 60).padStart(2, '0')}m`, ''); }
    else if (a.type === 'phaseSkip') log(`${cs}: ${a.ph} ya enviado (sesión anterior), omitido`, '');
    else if (a.type === 'phase') processMessages(flt, a.ph, PHASE_GEN[a.ph], autoSend);
    else if (a.type === 'riRestored') log(`${cs}: route info reciente (sesión anterior), restaurado`, '');
    else if (a.type === 'routeinfo') processMessages(flt, a.key, genRouteInfo, autoSend, a.significant);
  }
}

// 5.5.2 (A5): con FSUIPC dando datos, «Mi callsign» vacío o distinto de los vuelos de IVAO deja sin efecto el aterrizaje por FSUIPC
// (y la protección de la tarjeta): se avisa en el registro y en el estado de FSUIPC, una vez por valor y sesión.
// Revisión: al arrancar IVAO puede tardar en listar al piloto; el aviso sale solo tras OWN_CS_MISS pasadas seguidas sin coincidencia y,
// cuando coincide, el estado de FSUIPC vuelve a lo que mostraba y el valor puede volver a avisar si deja de coincidir
const ownCsWarned = new Set(), OWN_CS_MISS = 3;
let ownCsMiss = 0, ownCsPrev = null; // pasadas seguidas sin coincidencia · estado de FSUIPC antes del aviso
function opsCheckOwnCallsign() {
  const own = ($('fsuipcCs')?.value || '').trim().toUpperCase();
  if (own && flights[own]) {
    ownCsMiss = 0; ownCsWarned.clear();
    const el = $('fsuipcStatus');
    if (ownCsPrev && el && el.textContent === ownCsPrev.warn) { el.textContent = ownCsPrev.text; el.style.color = ownCsPrev.color; }
    ownCsPrev = null;
    return;
  }
  if (!fsuipcGetData(30000)) { ownCsMiss = 0; return; }
  if (++ownCsMiss < OWN_CS_MISS || ownCsWarned.has(own)) return;
  ownCsWarned.add(own);
  const msg = `FSUIPC conectado pero "Mi callsign" (${own || 'vacío'}) no coincide con tu callsign de IVAO: el aterrizaje se detectará por IVAO`;
  // Segunda revisión: un segundo aviso (otro valor) no pisa el estado guardado con el primer aviso
  const el = $('fsuipcStatus'); if (el) ownCsPrev = { ...(ownCsPrev || { text: el.textContent, color: el.style.color }), warn: msg };
  log(msg, 'wrn'); fsuipcSetStatus(msg, false);
}

async function processMessages(flt, phase, generatorFn, autoSend, requireSignificant = false) {
  try {
    const msgs = await generatorFn(flt);
    // 5.0 rc2 (vuelo 1): tras aterrizar el Fenix deja de consultar Hoppie en pocos minutos. Si ya no está
    // conectado, no se envía: se quedaría 24 h en cola y le llegaría en el siguiente vuelo. Queda «retenido».
    const hold = autoSend && phase === 'landed' && !(await opsAircraftOnline(flt.callsign));
    for (const m of msgs) {
      const key = `${phase}_${m.id}`;
      if (requireSignificant && m.significant === false) {
        log(`${m.label} ${flt.callsign}: sin info significativa, omitido`, '');
        recordSent(flt.callsign, flt.dep, flt.arr, phase, m.label, 'skip', m.body, key);
        continue;
      }
      flt.msgStatus[key] = hold ? 'held' : autoSend ? 'sending' : 'pending';
      flt.msgBodies[key] = m.body;
      if (hold) (flt.msgSentAt ||= {})[key] = Date.now(); // 5.5.4: hora del retenido, para el reenvío al reaparecer
      updateDashboard();
      if (hold) { log(`${m.label} ${flt.callsign}: retenido, ${opsHoldReason(flt.callsign)} (clic en la tarjeta para enviarlo)`, 'wrn'); recordSent(flt.callsign, flt.dep, flt.arr, phase, m.label, 'held', m.body, key); continue; }
      if (!autoSend) { log(`${m.label} generado para ${flt.callsign} (envío manual)`, ''); continue; }
      try {
        await sendTelex(flt.callsign, m.body, { auto: true, key });
        flt.msgStatus[key] = 'sent'; (flt.msgSentAt ||= {})[key] = Date.now();
        log(`✓ ${m.label} → ${flt.callsign}`, 'ok');
        recordSent(flt.callsign, flt.dep, flt.arr, phase, m.label, 'sent', m.body, key);
        await sleep(800);
      } catch (e) {
        flt.msgStatus[key] = 'error';
        NBV.sound.play('error');
        log(`✗ ${m.label} → ${flt.callsign}: ${e.message}`, 'err');
        recordSent(flt.callsign, flt.dep, flt.arr, phase, m.label, 'error', m.body, key);
      }
    }
  } catch (e) {
    log(`Error generando ${phase} para ${flt.callsign}: ${e.message}`, 'err');
  }
  updateDashboard(); updateStats();
}

// Conditional version: only sends if the message body contains significant info
// (SIGMETs, PIREPs, or notable ATC changes). Used for 15min post-departure check.


// ── 5.0 rc2: estado real de entrega (Hoppie: hora de recepción y de recogida por el avión) ──
// 5.5.2 (A3): además de figurar en online.html, el avión tiene que seguir recogiendo (NBV.opsLogic.listening). La causa del último
// «no» queda en opsHoldWhy para el texto del retenido (opsHoldReason); no se persiste
const opsHoldWhy = new Map();
async function opsAircraftOnline(cs) {
  let inList;
  try { inList = (await NBV.hoppie.online(true)).has(NBV.acars.to(cs).toUpperCase()); }
  catch (e) { return true; } // sin datos de Hoppie: se envía como antes
  const oldestPendingMs = inList ? await opsOldestPending(cs) : null;
  opsHoldWhy.set(cs, { inList, oldestPendingMs });
  return NBV.opsLogic.listening({ inList, oldestPendingMs, now: Date.now() });
}
function opsHoldReason(cs) {
  const w = opsHoldWhy.get(cs);
  return w?.inList && typeof w.oldestPendingMs === 'number'
    ? `el avión tiene un mensaje sin recoger desde ${new Date(w.oldestPendingMs).toISOString().substring(11, 16)}Z`
    : 'el avión ya no está conectado a Hoppie';
}
// 5.5.2 (A3): hora (ms) de recepción en Hoppie del mensaje más antiguo que espera al avión (dirigido a él, de cualquier remitente,
// sin «relayed») en su historial de 24 h; null si no hay ninguno o no se puede leer. Una consulta del avión los recoge todos.
// La red, como en opsTrackDelivery
async function opsOldestPending(cs) {
  const dest = NBV.acars.to(cs).toUpperCase();
  try {
    const station = ($('cS')?.value || '').trim().toUpperCase();
    const net = ((await NBV.hoppie.online()).get(station) || [])[0]?.net || 'IVAO';
    const now = Date.now(), h = await NBV.hoppie.history(dest, net);
    const skew = opsClockSkew(flights[cs], h.filter(x => x.from === station && x.to === dest));
    let oldest = null;
    for (const x of h) {
      if (x.to !== dest || x.relayed) continue;
      const t = opsHoppieRxMs(x.rx, now);
      if (t !== null && (oldest === null || t + skew < oldest)) oldest = t + skew;
    }
    return oldest;
  } catch (e) {
    log(`Hoppie: no se pudo leer el historial de ${dest} (${e.message}); la retención decide solo por la lista de conectados`, 'wrn');
    return null;
  }
}
// Texto completo normalizado; un mensaje troceado por hoppieSendTelex se compara con su primer paquete («[1/N] …»)
const norm = s => String(s || '').replace(/\s+/g, ' ').trim().toUpperCase();
const firstPacket = body => { const c = splitMsg(sanitizeForHoppie(body), 480); return c.length ? norm(c.length > 1 ? `[1/${c.length}] ${c[0]}` : c[0]) : ''; };
// 5.5.2 (A3, revisión): desfase reloj del PC − reloj de Hoppie (ms), con el último mensaje propio enviado a este avión que aparece en su
// historial: msgSentAt (hora del PC) frente a su recepción en Hoppie (rx, al minuto). 0 si no hay ninguno. Con el PC adelantado ~5 min,
// el TELEX propio recién enviado parecía esperar desde hacía más de 5 min y los LANDED se retenían. Vale también para los de otras estaciones
// Segunda revisión: un desfase de más de SKEW_MAX_MS (15 min) no es el reloj sino un casado equivocado (texto repetido de otra pierna): se ignora
const SKEW_MAX_MS = 15 * 60000;
function opsClockSkew(f, own) {
  const at = f?.msgSentAt || {}, bodies = f?.msgBodies || {};
  let best = -Infinity, skew = 0;
  for (const k of Object.keys(at)) {
    const want = firstPacket(bodies[k] || '');
    if (!want || !(at[k] > best)) continue;
    const x = own.filter(y => norm(y.text) === want).sort((a, b) => b.id - a.id)[0]; // el más reciente con ese texto (un reenvío pisa msgSentAt)
    const rx = x ? opsHoppieRxMs(x.rx, at[k]) : null;
    if (rx === null || Math.abs(Math.floor(at[k] / 60000) * 60000 - rx) > SKEW_MAX_MS) continue;
    best = at[k]; skew = Math.floor(at[k] / 60000) * 60000 - rx;
  }
  return skew;
}
// Hoppie da la recepción como «DD-HH:MMZ» (sin mes ni año): se reconstruye alrededor de `ref` (ms); null si no se puede
function opsHoppieRxMs(rx, ref) {
  const m = /^(\d{1,2})-(\d{2}):(\d{2})Z?$/.exec(String(rx || '').trim());
  if (!m || !ref) return null;
  const d = new Date(ref); let best = null;
  for (const dm of [-1, 0, 1]) { const t = Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + dm, +m[1], +m[2], +m[3]); if (best === null || Math.abs(t - ref) < Math.abs(best - ref)) best = t; }
  return Math.abs(best - ref) < 3 * 86400000 ? best : null;
}
// 5.5.2 (A4): los mensajes de llegada que el avión no recoge en 3 min pasan a «sin recoger» (tarjeta e historial); siguen
// pudiendo pasar a «recibido» (opsTrackDelivery) y se reenvían con un clic, como los retenidos
function opsCheckUnpicked(now) {
  for (const f of Object.values(flights)) {
    for (const k of NBV.opsLogic.unpicked(f, now, deliveryChecked.get(f.callsign) || 0)) {
      f.msgStatus[k] = 'unpicked';
      const row = [...msgHistory].reverse().find(m => m.cs === f.callsign && m.key === k);
      log(`⚠ ${row?.label || k.replace(/_/g, ' ').toUpperCase()} ${f.callsign}: sin recoger tras 3 min (clic en la tarjeta para reenviarlo)`, 'wrn');
      markHistoryStatus(f.callsign, k, 'unpicked');
    }
  }
}
let deliveryAt = 0;
const deliveryChecked = new Map(); // segunda revisión: callsign → hora de la última lectura correcta de su historial (la que cuenta para «sin recoger»)
const deliveredIds = new Set(); // 5.5 (G1): ids de Hoppie que ya confirmaron una clave; cada mensaje confirma como mucho una
async function opsTrackDelivery() {
  if (Date.now() - deliveryAt < 55000) return;
  const station = ($('cS')?.value || '').trim().toUpperCase(); if (!station) return;
  const pend = Object.values(flights).filter(f => Object.values(f.msgStatus || {}).some(TRACK));
  if (!pend.length) return;
  deliveryAt = Date.now();
  const net = ((await NBV.hoppie.online()).get(station) || [])[0]?.net || 'IVAO';
  for (const f of pend) await opsCheckDelivery(f, station, net);
}
// 5.5.4: el Fenix borra el init del MCDU al aterrizar y deja de consultar Hoppie. Un LANDED/IN retenido (de menos de 60 min) sale solo, una vez, en
// cuanto el avión vuelve a escuchar. Hoppie es pull: no se puede forzar la consulta. Una sola vez: manualSend lo saca de «held» (sent, sending o error)
let resendAt = 0;
async function opsResendHeld() {
  if (Date.now() - resendAt < 55000) return;
  resendAt = Date.now();
  for (const f of Object.values(flights)) {
    const keys = NBV.opsLogic.resendable(f, Date.now());
    if (!keys.length || !(await opsAircraftOnline(f.callsign))) continue;
    for (const k of keys) {
      log(`${k.replace(/_/g, ' ').toUpperCase()} ${f.callsign}: el avión vuelve a consultar Hoppie, se envía lo retenido`, 'ops');
      await manualSend(f.callsign, k);
    }
  }
}
const TRACK = s => s === 'sent' || s === 'unpicked'; // 5.5.2 (A4): un «sin recoger» que el avión recoge después pasa a recibido
// Claves de un vuelo (todas, o solo `only`) que el avión ya recogió según el historial de Hoppie → «delivered». Revisión: la usa también
// manualSend antes de reenviar un «sin recoger» (la comprobación periódica va cada 55 s y podía no haberlo visto aún)
async function opsCheckDelivery(f, station, net, only = null) {
  const dest = NBV.acars.to(f.callsign).toUpperCase();
  const t0 = Date.now();
  let h; try { h = await NBV.hoppie.history(dest, net); } catch (e) { return; }
  if (!only) deliveryChecked.set(f.callsign, t0);
  const mine = h.filter(x => x.from === station && x.to === dest && x.relayed).sort((a, b) => a.id - b.id);
  const sentAt = f.msgSentAt || {};
  const keys = Object.keys(f.msgStatus).filter(k => TRACK(f.msgStatus[k]) && (!only || k === only)).sort((a, b) => (sentAt[a] || 0) - (sentAt[b] || 0));
  for (const k of keys) {
    const want = firstPacket(f.msgBodies?.[k] || '');
    if (!want) continue;
    // Recibido por Hoppie no antes del envío (resolución de minuto); sin hora legible decide el texto y el id.
    // 5.5.2 (A6): 10 min de margen por el reloj del PC (con 1 min, un PC adelantado daba la recogida por anterior al envío)
    const from = sentAt[k] ? Math.floor(sentAt[k] / 60000) * 60000 - 600000 : null;
    const hit = mine.find(x => {
      if (deliveredIds.has(x.id) || norm(x.text) !== want) return false;
      const rx = from === null ? null : opsHoppieRxMs(x.rx, sentAt[k]);
      return rx === null || rx >= from;
    });
    if (hit) { deliveredIds.add(hit.id); f.msgStatus[k] = 'delivered'; (f.msgDelivered ||= {})[k] = hit.relayed; markHistoryDelivered(f.callsign, k, hit.relayed); }
  }
}

// Manual send from dashboard
// Segunda revisión: candado síncrono por clave; con un «sin recoger», la comprobación previa espera a Hoppie y un doble clic lo enviaba dos veces
const manualSending = new Set();
async function manualSend(cs, key) {
  const lock = `${cs}|${key}`;
  if (manualSending.has(lock)) { log(`${key} → ${cs}: ya se está enviando`, ''); return; }
  manualSending.add(lock);
  try { await manualSendNow(cs, key); } finally { manualSending.delete(lock); }
}
async function manualSendNow(cs, key) {
  const flt = flights[cs];
  const body = flt?.msgBodies?.[key];
  if (!body) { log(`${key} → ${cs}: contenido no disponible, regenera el mensaje`, 'wrn'); return; }
  // Revisión del punto 4: un «sin recoger» que el avión ya recogió no se reenvía (se duplicaría): pasa a recibido
  if (flt.msgStatus[key] === 'unpicked') {
    const station = ($('cS')?.value || '').trim().toUpperCase();
    try { if (station) await opsCheckDelivery(flt, station, ((await NBV.hoppie.online()).get(station) || [])[0]?.net || 'IVAO', key); }
    catch (e) { log(`${key} → ${cs}: no se pudo comprobar en Hoppie si ya lo recogió (${e.message}); se reenvía`, 'wrn'); }
    if (flt.msgStatus[key] === 'delivered') { log(`${key} → ${cs}: el avión ya lo había recogido, no se reenvía`, 'ok'); updateDashboard(); updateStats(); return; }
  }
  flt.msgStatus[key] = 'sending';
  updateDashboard();
  try {
    await sendTelex(cs, body, { auto: false, key });
    flt.msgStatus[key] = 'sent'; (flt.msgSentAt ||= {})[key] = Date.now();
    log(`✓ ${key} → ${cs} (manual)`, 'ok');
    recordSent(cs, flt.dep, flt.arr, /^oooi_/.test(key) ? key : key.split('_')[0], key, 'sent', body, key); // OOOI: la fase es la clave entera (como el envío automático)
  } catch (e) {
    flt.msgStatus[key] = 'error';
    log(`✗ ${key} → ${cs}: ${e.message}`, 'err');
  }
  updateDashboard(); updateStats();
}

