function updateDashboard() {
  const dash = $('dashboard');
  const activeFlights = Object.values(flights); // 5.5.2 (A1): también los desconectados de IVAO, en gris (offline() los borra a su tiempo)
  if (activeFlights.length === 0) {
    const run = !!monitorInterval;
    dash.innerHTML = `<div class="dash-empty" id="dashEmpty">${NBV.ui.icon('radar', 'big')}
      <b>${run ? 'Escuchando la frecuencia' : 'La torre está en silencio'}</b>
      <p>${run ? `Aún no hay vuelos ${esc(($('cA')?.value || 'NBV').toUpperCase())} conectados a IVAO. En cuanto un piloto conecte aparecerá aquí y recibirá su bienvenida automáticamente.` : 'Inicia el monitor para detectar los vuelos de AirNubeiro en IVAO y enviarles meteo, tráfico y loadsheet en cada fase.'}</p>
      ${run ? '' : `<button type="button" class="btn-pri" data-click="toggleMonitor">${NBV.ui.icon('play')}Iniciar monitor</button>`}</div>`;
    return;
  }
  const order = { PREFLIGHT: 0, ENROUTE: 1, DESCENT: 2, LANDED: 3 };
  activeFlights.sort((a, b) => (order[a.phase] ?? 9) - (order[b.phase] ?? 9));
  const PH = { PREFLIGHT: 'Preflight', ENROUTE: 'En ruta', DESCENT: 'Descenso', LANDED: 'En tierra' };
  const PEND = 'pendiente: el avión no consulta — se enviará al reconectar (clic para enviar ya)';
  const ST = { sent: 'enviado — esperando a que el avión lo recoja', delivered: 'entregado al avión', held: PEND, unpicked: PEND, sending: 'enviando', pending: 'pendiente — clic para enviar', error: 'error — clic para reintentar' };

  const logRows = new Map(NBV.flightLog.list().map(e => [e.id, e])); // 6.0 (fase 2): marcas de alerta de cada vuelo (flt.logId)
  dash.innerHTML = activeFlights.map(f => {
    NBV.ui.stats.seen(f.callsign);
    const ph = String(f.phase || '').toLowerCase();
    const pct = f.phase === 'LANDED' ? 100 : Math.max(0, Math.min(100, Math.round(f.progressPct || 0)));
    const e = etaInfo({ arrivalDist: f.arrivalDist, gs: f.gs, lat: f.lat, lon: f.lng, arr: f.arr });
    const d = [];
    d.push(['ALT', f.alt > 0 ? 'FL' + Math.round(f.alt / 100) : f.onGround ? 'GND' : '—']);
    d.push(['GS', f.gs > 0 ? f.gs + ' kt' : '—']);
    if (e.eta && f.phase !== 'LANDED') d.push(['ETA', e.eta]);
    if (e.dist != null) d.push(['DEST', e.dist + ' nm']);
    if (f.estEnrouteMin > 0) d.push(['EET', `${Math.floor(f.estEnrouteMin / 60)}h${String(Math.round(f.estEnrouteMin % 60)).padStart(2, '0')}`]);
    if (f.enrouteStart) d.push(['ENR', Math.round((Date.now() - f.enrouteStart) / 60000) + ' min']);
    if (f.ivaoState) d.push(['ST', f.ivaoState]);
    if (f.routeInfoCount > 0) d.push(['RI', '×' + f.routeInfoCount]);
    const msgsHtml = Object.entries(f.msgStatus || {}).map(([key, s]) => {
      const label = key.replace(/_/g, ' ').toUpperCase();
      const icHtml = s === 'delivered' ? NBV.ui.icon('check') : s === 'sent' ? NBV.ui.icon('clock') : s === 'error' ? NBV.ui.icon('refresh') : (s === 'pending' || s === 'held' || s === 'unpicked') ? NBV.ui.icon('send') : '';
      const tip = s === 'delivered' && f.msgDelivered?.[key] ? `entregado al avión ${f.msgDelivered[key]}` : ST[s] || s;
      return (s === 'pending' || s === 'error' || s === 'held' || s === 'unpicked')
        ? `<button type="button" class="flt-msg ${esc(s)}" title="${esc(label)}: ${esc(tip)}" data-click="manualSend|${esc(f.callsign)}|${esc(key)}">${icHtml}${esc(label)}</button>`
        : `<span class="flt-msg ${esc(s)}" title="${esc(label)}: ${esc(tip)}">${icHtml}${esc(label)}</span>`;
    }).join('');
    const src = f.srcSim ? ['src-sim', 'SIM'] : f.srcPhpvms ? ['src-phpvms', 'phpVMS'] : ['src-ivao', 'IVAO'];
    const meta = [esc(f.aircraft || ''), f.registration ? esc(f.registration) : '', [f.pilotIdent, f.pilotName].filter(Boolean).map(esc).join(' · ')].filter(Boolean);
    { const ac = NBV.acars.to(f.callsign); if (ac !== String(f.callsign).toUpperCase()) meta.push(`ACARS ${esc(ac)}`); }
    if (f.tech) { // 5.2: TechLog de tu avión
      const t = f.tech, nDef = (t.deferred?.length || 0) + (t.open?.length || 0), bad = t.dispatch !== 'GO' || /NOT/.test(t.ready) || f.techMismatch;
      meta.push(`<b class="${bad ? 'tech-bad' : 'tech-ok'}" title="TechLog: ${esc(t.reg)}${f.techMismatch ? ' ≠ ' + esc(f.registration) : ''}">TECH ${esc(t.dispatch)} · ${esc(t.ready)}${nDef ? ` · ${Number(nDef)} def.` : ''}${f.techMismatch ? ' · LIVERY ' + esc(t.reg) : ''}</b>`);
    }
    const cs = f.callsign;
    const clickHtml = NBV.ui.embed ? ` data-cs="${esc(cs)}" tabindex="0" role="button" aria-label="${esc(cs)}: escribir un mensaje" data-click="opsCompose|${esc(cs)}" data-keydown="opsCompose|${esc(cs)}" data-key="Enter"` : '';
    const offHtml = f.offlineSince ? `<div class="fc-off">sin señal IVAO desde ${esc(new Date(f.offlineSince).toISOString().substring(11, 16))}Z</div>` : '';
    const standHtml = opsStandLine(f); // 5.5.2 (P8)
    // 6.0 (fase 2): una etiqueta ámbar por alerta de despacho de la fila del registro, y «desconectado» sin señal de IVAO
    const r = logRows.get(f.logId) || {}, al = [[r.alDiv, 'DESVÍO'], [r.alDep, `RETRASO +${r.alDep?.min}`], [r.alArr, `LLEG +${r.alArr?.min}`], [r.alLost, 'PERDIDO']].filter(([m]) => m?.t);
    const alHtml = al.length || f.offlineSince ? `<div class="fc-al">${al.map(([m, txt]) => `<span title="${esc(m.txt || '')}">${esc(txt)}</span>`).join('')}${f.offlineSince ? '<span>desconectado</span>' : ''}</div>` : '';
    return `<article class="flt-card ph-${esc(ph)}${f.offlineSince ? ' off' : ''}"${clickHtml}>
      <div class="fc-top"><div class="flt-cs">${esc(cs)}</div>${NBV.ui.embed ? `<span class="fc-cmp">${NBV.ui.icon('pen')}Escribir</span>` : ''}<span class="flt-phase ${esc(ph)}">${esc(PH[f.phase] || f.phase)}</span></div>
      ${offHtml}${alHtml}${standHtml}
      <div class="fc-route"><span class="ap">${esc(f.dep || '----')}</span><div class="fc-bar"><i style="width:${Number(pct)}%"></i><svg class="ic" style="left:${Number(pct)}%" aria-hidden="true"><use href="#i-plane"/></svg></div><span class="ap">${esc(f.arr || '----')}</span></div>
      <div class="flt-data">${d.map(([k, v]) => `<div class="flt-d">${k} <span>${esc(String(v))}</span></div>`).join('')}</div>
      <div class="fc-meta">${meta.map(mHtml => `<span>${mHtml}</span>`).join('<span class="sep"></span>')}<span class="${esc(src[0])}" style="margin-left:auto">${esc(src[1])}</span></div>
      ${f.phase === 'LANDED' && Object.values(f.msgStatus || {}).includes('held') ? `<div class="fc-off">${NBV.acProfiles.get(f.aircraft).arrival === 'clearsInit' ? 'retenido — normal en Fenix (borra el init al aterrizar); si vuela FBW, revisar' : 'avión desconectado: reintroducir FLT NBR + NOTIFY en el MCDU'}</div>` : ''}
      ${msgsHtml ? `<div class="flt-msgs">${msgsHtml}</div>` : ''}
    </article>`;
  }).join('');
}

// 5.5.2 (P8): puerta del vuelo y estado de su autorización de rodaje por CPDLC (encargo de nbv_taxi_clr, que lleva el ACARS).
