const OPS_STATE_KEY = 'an_ops_state', OPS_STATE_MAX_AGE = 20 * 60000, OPS_RESTORE_REG_MS = 6 * 3600000;

function opsSaveState() {
  try {
    const keep = {};
    for (const [cs, f] of Object.entries(flights)) if (Date.now() - (f.lastSeen || 0) < OPS_STATE_MAX_AGE) { const { _pilot, ...rest } = f; keep[cs] = rest; } // 5.5.2: _pilot no se guarda
    localStorage.setItem(OPS_STATE_KEY, JSON.stringify({ t: Date.now(), running: !!monitorInterval, total: totalMsgsSent, flights: keep }));
  } catch (e) { /* cuota llena: se omite */ }
}

function opsRestoreState() {
  let st = null; try { st = JSON.parse(localStorage.getItem(OPS_STATE_KEY)); } catch (e) {}
  if (!st?.flights) return null;
  let n = 0;
  for (const [cs, f] of Object.entries(st.flights)) {
    if (Date.now() - (f.lastSeen || 0) > OPS_STATE_MAX_AGE) continue;
    // Envíos que quedaron a medias al recargar → pendientes de reenvío manual
    for (const k of Object.keys(f.msgStatus || {})) if (f.msgStatus[k] === 'sending') f.msgStatus[k] = 'error';
    // Revisión del punto 4: recargar entre el aterrizaje (sent.landed = true, síncrono) y el envío de sus mensajes (asíncrono) los perdía.
    // Solo la fase en curso, si no tiene ninguna clave en el vuelo ni entrada en el registro antiduplicado (6 h, sin PHASE_DEDUP: pasados
    // 60/90 min se reenviaba). La reserva «~envio» no cuenta: no dice qué ventana la hizo, y la que recarga suele ser la que la tenía
    const ph = String(f.phase || '').toLowerCase(), inReg = k => Date.now() - (sentRegistry[k] || 0) < OPS_RESTORE_REG_MS;
    if (f.sent?.[ph] && !Object.keys(f.msgStatus || {}).some(k => k.startsWith(ph + '_')) && !inReg(dedupKey(cs, f.dep, f.arr, ph)) && !inReg(`${cs}___${ph}`)) f.sent[ph] = false;
    flights[cs] = { ...f, msgBodies: f.msgBodies || {}, msgStatus: f.msgStatus || {} }; n++;
  }
  msgCountRestore(st.total);
  if (n) log(`Estado restaurado: ${n} vuelo(s) de la sesión anterior`, 'ops');
  return st;
}

