// ══════════════════════════════════════════════════════════════════
//  INTEGRACIONES DEL OPS (5.2): TechLog de tu avión y comprobación de PIREP
//  · TechLog (core/20-techlog.js): solo para tu vuelo («Mi callsign» de FSUIPC) y con el OPS abierto desde el
//    servidor local. Estado técnico en la tarjeta, TELEX «TECH STATUS» en el preflight, aviso si la librea
//    cargada no es la matrícula asignada, y la toma y los defectos del vuelo en el registro.
//  · PIREP (core/21-pirep.js): con phpVMS activado, cada pierna completada se contrasta con su PIREP.
// ══════════════════════════════════════════════════════════════════
let techlogLastAt = 0, techlogLastFlightAt = 0, pirepLastAt = 0;
const TECHLOG_EVERY = 60000, PIREP_EVERY = 120000;
const opsOwnCallsign = () => ($('fsuipcCs')?.value || '').trim().toUpperCase();

// Estado técnico de tu avión → tarjeta del vuelo (antes de generar los mensajes de la pasada)
async function opsTechlogTick(now) {
  if (!NBV.techlog.enabled()) return;
  if (!NBV.techlog.available()) { NBV.techlog.setStatus('Abre el OPS con START-ACARS en el PC del simulador para leer TechLog', false); return; }
  if (now - techlogLastAt < TECHLOG_EVERY) return;
  techlogLastAt = now;
  const cs = opsOwnCallsign(), flt = cs ? flights[cs] : null;
  try {
    const s = await NBV.techlog.snapshot();
    const nDef = s.deferred.length + s.open.length;
    NBV.techlog.setStatus(`Conectado · ${s.reg || 'sin avión'} · DISPATCH ${s.dispatch} · ${s.ready}${nDef ? ` · ${nDef} defecto(s)` : ''}${cs ? '' : ' · indica «Mi callsign» en FSUIPC'}`, true);
    if (!flt) return;
    const prev = flt.tech;
    flt.tech = s;
    const planned = String(flt.registration || '').toUpperCase().replace(/-/g, '');
    flt.techMismatch = !!(planned && s.reg && planned !== s.reg.replace(/-/g, ''));
    if (flt.techMismatch && !prev?.mismatchLogged) { log(`TechLog ${cs}: librea cargada ${s.reg}, avión asignado ${flt.registration}`, 'wrn'); s.mismatchLogged = true; }
    else if (prev?.mismatchLogged) s.mismatchLogged = true;
    if (prev && (prev.dispatch !== s.dispatch || prev.ready !== s.ready)) log(`TechLog ${cs}: DISPATCH ${s.dispatch} · ${s.ready}`, s.dispatch === 'GO' ? 'ops' : 'wrn');
  } catch (e) { NBV.techlog.setStatus(e.message, false); }
}

// TELEX «TECH STATUS» del preflight (solo tu vuelo y con TechLog accesible)
async function opsTechStatusMessage(flt) {
  if (!NBV.techlog.enabled() || !NBV.techlog.available() || flt.callsign !== opsOwnCallsign()) return null;
  const s = flt.tech || await NBV.techlog.snapshot();
  return { id: 'techlog', label: 'TECH STATUS', body: NBV.techlog.statusText(s, { cs: flt.callsign, plannedReg: flt.registration }) };
}

// 6.0: informe de fin de vuelo, una sola vez por pierna completa y reciente. reportAt queda en el registro (pegajoso al
// fusionar ventanas), así que ni una recarga ni otra ventana del OPS lo repiten; las piernas con el ON de hace más de
// REPORT_MAX_AGE_MS (registro antiguo al actualizar, OPS cerrado horas) no se avisan ni se marcan.
const REPORT_MAX_AGE_MS = 2 * 3600000;
function opsReportTick(now) {
  for (const e of NBV.flightLog.list('', now)) {
    if (e.reportAt || !e.t?.on || now - e.t.on >= REPORT_MAX_AGE_MS) continue;
    try {
      const r = NBV.flightReport.build(e, NBV.acProfiles.get(e.ac), now);
      if (!r.complete) continue;
      // claim relee lo guardado: si otra ventana del OPS ya lo envió, aquí no se repite
      if (NBV.flightLog.claim(e.id, 'reportAt', now) && discordEvReport()) discordNotifyReport(e, r);
    } catch (err) { log(`Informe ${e.cs || '?'}: ${err.message}`, 'err'); }
  }
}

// 6.0 (fase 2): alertas de despacho (NBV.dispatch) y tarjeta viva de Discord de cada vuelo IVAO en línea (online: los callsign
// que lista IVAO en esta pasada; sin él, los vuelos sin offlineSince). La marca al* va en la fila del registro y claim relee lo
// guardado: una vez por vuelo y tipo, también tras recargar y con dos ventanas del OPS. A discordCardSync va la fila de la caché
// que devuelve track (la sincronización le anota dcAt/dcMsg/dcGone), nunca una copia de list()
const DISPATCH_FIELD = { div: 'alDiv', dep: 'alDep', arr: 'alArr', lost: 'alLost' };
function opsDispatchAlert(e, cs, a, now) {
  const mark = { t: now, txt: a.text, ...(a.min != null ? { min: a.min } : {}) };
  if (!NBV.flightLog.claim(e.id, DISPATCH_FIELD[a.type], now, mark)) return;
  log(`⚠ ${cs}: ${a.text}`, 'wrn');
  NBV.sound.play('error'); // no hay sonido propio de alerta: el de error es el de aviso
  if (discordEvDispatch()) discordNotifyDispatch(e, a);
}
function opsDispatchTick(now, online = null) {
  const css = online ? [...online] : Object.keys(flights).filter(cs => !flights[cs].offlineSince);
  for (const cs of css) {
    const flt = flights[cs], e = flt ? NBV.flightLog.track(flt, now) : null; // null: vuelo solo de phpVMS (sin fila, tarjeta ni alertas)
    if (!e) continue;
    flt.logId = e.id;
    for (const a of NBV.dispatch.evaluate(flt, now, { apt: NBV.apt.known })) opsDispatchAlert(e, cs, a, now);
    discordCardSync(e, flt, now, { log });
  }
}
// 6.0 (fase 2): el vuelo deja de aparecer en IVAO. En el aire → alerta «Desconexión en vuelo»; la tarjeta se actualiza igual
function opsDispatchOffline(cs, now) {
  const e = NBV.flightLog.offline(cs, now), flt = flights[cs];
  if (!e || !flt) return;
  const a = NBV.dispatch.lost(flt);
  if (a) opsDispatchAlert(e, cs, a, now);
  discordCardSync(e, flt, now, { log });
}

// 6.0 (fase 2): resumen diario de Discord del día UTC que termina, una vez por día. Ventana: de 23:59Z (día = hoy) a 00:05Z
// (día = ayer), por si ninguna pasada cae justo en 23:59Z. La marca nbv_dc_daily (fecha) se relee de localStorage justo antes
// de escribirla (como claim): con dos ventanas del OPS solo envía una. Sale con cualquier fila del día (también solo vuelos sin aterrizar);
// sin ninguna, se marca sin enviar nada; con filas y sin el aviso activo (discordEvDaily), no se marca
const DAILY_KEY = 'nbv_dc_daily', DAY_MS = 86400000;
function opsDailyTick(now) {
  const d = new Date(now), min = d.getUTCHours() * 60 + d.getUTCMinutes(), today = Math.floor(now / DAY_MS) * DAY_MS;
  const start = min >= 23 * 60 + 59 ? today : min < 5 ? today - DAY_MS : null;
  if (start == null) return;
  const day = new Date(start).toISOString().slice(0, 10);
  if (NBV.store.raw(DAILY_KEY) === day) return;
  // 6.0 (revisión): con filas y sin poder enviarlo (casilla desmarcada, webhook aún sin cargar) no se marca el día: sale en una pasada
  // posterior de la ventana si el webhook ya está; se marca al enviarlo o si el día no tiene nada que contar
  const sum = NBV.dispatch.daySummary(NBV.flightLog.dayRows(start, now), start), send = sum.lines.length > 0 && discordEvDaily();
  if (sum.lines.length && !send) return;
  try { localStorage.setItem(DAILY_KEY, day); } catch (e) { return; } // sin almacenamiento no hay forma de no repetirlo
  if (send) discordNotifyDaily(sum);
}

// Tras cada pasada: la toma y los defectos de tu vuelo (TechLog) y la comprobación de PIREP (phpVMS)
async function opsRegistroIntegraciones(now) {
  try { opsDailyTick(now); } catch (err) { log(`Resumen diario: ${err.message}`, 'err'); }
  opsReportTick(now);
  const recent = NBV.flightLog.list('', now).filter(e => now - (e.last || 0) < 24 * 3600000);
  const own = opsOwnCallsign();
  if (own && NBV.techlog.enabled() && NBV.techlog.available() && now - techlogLastFlightAt >= TECHLOG_EVERY) {
    const e = recent.find(x => x.cs === own && x.st === 'completado' && !x.tech?.closed);
    if (e) {
      techlogLastFlightAt = now;
      try {
        const rec = await NBV.techlog.flightFor(e);
        if (rec) {
          NBV.flightLog.annotate(e.id, { tech: rec }, now);
          if (rec.closed) log(`TechLog ${e.cs}: toma ${rec.landing ? rec.landing.vs + ' fpm' : '—'}${rec.defects.length ? ` · ${rec.defects.length} defecto(s) en vuelo` : ''}`, rec.defects.length ? 'wrn' : 'ops');
        }
      } catch (err) { /* TechLog cerrada: se reintenta en la siguiente pasada */ }
    }
  }
  if (!$('phpvmsEn')?.checked || now - pirepLastAt < PIREP_EVERY) return;
  pirepLastAt = now;
  for (const e of recent) {
    if (e.st !== 'completado' || e.pirep?.final) continue;
    let pirep = null;
    if (e.pirepId) { try { pirep = await NBV.pirepCheck.fetchPirep(phpvmsBase(), e.pirepId, await phpvmsHeaders()); } catch (err) { continue; } }
    const r = NBV.pirepCheck.evaluate(e, pirep, now);
    if (!r) continue;
    if (r.label !== e.pirep?.label || (r.issues || []).join() !== (e.pirep?.issues || []).join()) {
      if (r.level === 'wrn' || r.level === 'err') log(`PIREP ${e.cs} ${e.dep}→${e.arr}: ${r.label}${r.issues.length ? ' — ' + r.issues.join('; ') : ''}`, r.level === 'err' ? 'err' : 'wrn');
      else if (r.final) log(`PIREP ${e.cs} ${e.dep}→${e.arr}: ${r.label}`, 'ok');
    }
    NBV.flightLog.annotate(e.id, { pirep: { ...r, at: now } }, now);
  }
}

// «Preparar» un PIREP manual cuando vmsACARS no lo presentó: copia los datos y abre el formulario de phpVMS
async function flogPirepPrep(...idParts) { // id «callsign|firstSeen» partido por NBV.act (flogId)
  const id = flogId(idParts), e = NBV.flightLog.list().find(x => x.id === id);
  if (!e) return;
  const text = NBV.pirepCheck.manualText(e);
  try { await navigator.clipboard.writeText(text); ss('ok', 'Datos del PIREP copiados: pégalos en el formulario de phpVMS'); }
  catch (err) { window.prompt('Copia estos datos para el PIREP manual:', text); }
  window.open(`${phpvmsBase()}/pireps/create`, '_blank', 'noopener');
}
// 6.0: «Copiar para PIREP» de la ficha del informe: solo copia (sirve para piernas de otros pilotos; no abre el formulario de phpVMS)
async function flogReportCopy(...idParts) {
  const id = flogId(idParts), e = NBV.flightLog.list().find(x => x.id === id);
  if (!e) return;
  const text = NBV.pirepCheck.manualText(e);
  try { await navigator.clipboard.writeText(text); ss('ok', 'Informe copiado: pégalo en el PIREP'); }
  catch (err) { window.prompt('Copia el informe para el PIREP:', text); }
}

// ── OOOI (5.5): OUT/OFF/ON/IN de tu avión a partir de las muestras de FSUIPC (NBV.oooi, sin DOM) ──
// Un estado por callsign; la hora de cada evento es la de la condición (no la de la muestra). Se guarda en flt.oooi
// (opsSaveState lo conserva) y llega al registro de vuelos. Solo tu avión: «Mi callsign» de FSUIPC con vuelo en el OPS.
const oooiState = {}, simRoll = {}; // simRoll: inicio de la rodadura lenta (GS < 40 kt) de tu avión, por callsign
function opsOooiSample(sim) {
  const cs = opsOwnCallsign(), flt = cs ? flights[cs] : null;
  if (!flt || !sim) return;
  flt.oooi = flt.oooi || {};
  const now = sim.ts || Date.now();
  // Se reconstruye si falta o si el vuelo perdió tiempos que el estado ya tenía (pierna nueva con el mismo callsign: flt.oooi vuelve a {})
  if (!oooiState[cs] || Object.keys(oooiState[cs].t).some(k => !flt.oooi[k])) oooiState[cs] = NBV.oooi.fromTimes(flt.oooi);
  const r = NBV.oooi.step(oooiState[cs], { onGround: !!sim.onGround, gs: sim.groundSpeed || 0 }, now, { phase: flt.phase });
  oooiState[cs] = r.st;
  // 5.5.2 (P6): con FSUIPC, la posición y la velocidad reales de tu avión deciden cuándo ha dejado la pista (en cada muestra)
  if (sim.onGround && isFinite(sim.lat) && isFinite(sim.lon)) opsTaxiCheck(flt, [sim.lat, sim.lon], sim.groundSpeed || 0).catch(e => log(`${cs}: autorización de rodaje: ${e.message}`, 'err'));
  for (const ev of r.events) {
    flt.oooi[ev.type.toLowerCase()] = ev.t;
    log(`OOOI ${cs} ${ev.type} ${new Date(ev.t).toISOString().substring(11, 16)}Z`, 'ops');
  }
  // 5.5.2 (A2): el aterrizaje de tu avión lo da el simulador y los mensajes de llegada salen en el rodaje, cuando el avión aún consulta Hoppie
  // (IVAO puede no listarlo durante minutos). Revisión: tras el ON hace falta además GS < 40 kt sostenida 10 s (NBV.opsLogic.rollout), para que
  // una toma y despegue o un go-around no den el vuelo por aterrizado; si FSUIPC vuelve a dar el avión en el aire, la fase vuelve a darla IVAO.
  // Solo la ventana con el monitor en marcha; el antiduplicado compartido se relee antes.
  const ro = NBV.opsLogic.rollout(simRoll[cs], { onGround: !!sim.onGround, gs: sim.groundSpeed || 0 }, now); simRoll[cs] = ro.since;
  if (!sim.onGround && flt.landedBySim) { flt.landedBySim = null; log(`${cs}: FSUIPC da el avión en el aire (toma y despegue o go-around): la fase vuelve a darla IVAO`, 'wrn'); }
  const from = flt.phase;
  const landed = ro.done && !!flt.oooi.on && !!monitorInterval && NBV.opsLogic.simLanding(flt, { type: 'ON', t: now });
  if (landed) {
    log(`${cs}: ${from} → LANDED (FSUIPC)`, 'ops');
    // Revisión: con dos ventanas del OPS con el monitor en marcha las dos reciben el ON; la primera reserva el envío (como opsOooiSend)
    reloadSentRegistry();
    const landClaim = dedupKey(cs, flt.dep, flt.arr, 'landed') + '~envio';
    if (Date.now() - (sentRegistry[landClaim] || 0) < OOOI_CLAIM_MS) { flt.sent.landed = true; log(`${cs}: mensajes de llegada omitidos (otra ventana del OPS los está enviando)`, 'ops'); }
    else {
      sentRegistry[landClaim] = Date.now(); saveSentRegistry(); // síncrono hasta aquí: la otra ventana ya ve la reserva
      NBV.sound.play('phase'); if (flt.srcPhpvms) discordNotifyPhase(flt, from, 'LANDED'); // 6.0 (fase 2): un vuelo IVAO lo lleva su tarjeta
      opsRunActions(flt, flt._pilot || {}, $('cAuto').value === '1');
    }
    updateDashboard(); updateStats();
  }
  if (!r.events.length && !landed) return;
  NBV.flightLog.track(flt, Date.now());
  opsSaveState(); // 5.5 (G5): una recarga justo después del evento no lo repite (el escaneo solo guarda al final de cada pasada)
  for (const ev of r.events) opsOooiSend(flt, ev.type).catch(e => log(`OOOI ${cs} ${ev.type}: ${e.message}`, 'err'));
}

// TELEX OOOI a tu avión (opcional, casilla «oooiTx»): uno por evento; el IN lleva el resumen. Dedup por callsign+ruta+evento (90 min, persiste),
// y si Hoppie falla, reintentos a los 30 s y a los 120 s; al tercer fallo queda «error» en el historial. flt.msgStatus/msgBodies/msgSentAt
// hacen que la tarjeta y el historial lo sigan como cualquier otro mensaje (enviado → recibido).
// Varias ventanas del OPS reciben las mismas muestras (la embebida en el ACARS y otra abierta aparte): solo envía la que tiene el monitor
// en marcha, y antes de enviar se relee el registro compartido y se reserva el envío (OOOI_CLAIM_MS) para que otra ventana no lo repita.
const OOOI_DEDUP_MS = 90 * 60000, OOOI_RETRY_MS = [30000, 120000], OOOI_CLAIM_MS = 60000;
async function opsOooiSend(flt, ev, attempt = 0, body = null) {
  // Un reintento que sale sin enviar no deja el «sending» guardado (sin botón hasta recargar): «error» si se desactivó la casilla (reenviable), «sent» si otra ventana ya lo envió
  const endRetry = st => { if (!attempt) return; const g = flights[flt.callsign] || flt, k = 'oooi_' + ev.toLowerCase(); if (g.msgStatus?.[k] === 'sending') { g.msgStatus[k] = st; if (st === 'sent') (g.msgSentAt ||= {})[k] = Date.now(); opsSaveState(); updateDashboard(); } };
  if (!$('oooiTx')?.checked) { endRetry('error'); return; }
  const cs = flt.callsign, key = 'oooi_' + ev.toLowerCase();
  if (!attempt && !monitorInterval) { log(`OOOI TELEX ${cs} ${ev}: no enviado, el monitor de esta ventana está detenido`, ''); return; }
  // La clave de dedup no lleva flt.firstSeen: un vuelo recreado (recarga, otra ventana) con las mismas muestras tiene otro firstSeen y repetiría el TELEX.
  // Una pierna nueva con la misma ruta pasa pasados 90 min. Un reintento tras fallo no mira el monitor (ya pasó el control al empezar).
  const dkey = key, claim = dedupKey(cs, flt.dep, flt.arr, key) + '~envio';
  reloadSentRegistry();
  if (wasSentRecently(cs, flt.dep, flt.arr, dkey, OOOI_DEDUP_MS)) { log(`OOOI TELEX omitido (dedup) ${cs} ${ev}`, 'ops'); endRetry('sent'); return; }
  if (!attempt && Date.now() - (sentRegistry[claim] || 0) < OOOI_CLAIM_MS) { log(`OOOI TELEX omitido (otra ventana del OPS lo está enviando) ${cs} ${ev}`, 'ops'); return; }
  sentRegistry[claim] = Date.now(); saveSentRegistry(); // síncrono hasta aquí: otra ventana del mismo hilo ya ve la reserva
  body = body || NBV.oooi.telexText(cs, flt.dep, flt.arr, flt.oooi, ev);
  const f = () => flights[cs] || flt; // el escaneo sustituye el objeto del vuelo: se anota siempre en el vigente
  // Como los LANDED (processMessages): si el avión ya no está en Hoppie, el IN se retiene; la tarjeta permite enviarlo a mano
  if (ev === 'IN' && !(await opsAircraftOnline(cs))) {
    const g = f(); g.msgStatus[key] = 'held'; (g.msgBodies ||= {})[key] = body; (g.msgSentAt ||= {})[key] = Date.now();
    log(`OOOI IN ${cs}: retenido, ${opsHoldReason(cs)} (clic en la tarjeta para enviarlo)`, 'wrn');
    recordSent(cs, g.dep, g.arr, dkey, key, 'held', body, key);
    updateDashboard();
    return;
  }
  try {
    await sendTelex(cs, body, { auto: true, key });
  } catch (e) {
    if (attempt < OOOI_RETRY_MS.length) {
      log(`OOOI ${cs} ${ev}: Hoppie falló (${e.message}), reintento en ${OOOI_RETRY_MS[attempt] / 1000} s`, 'wrn');
      const g = f(); if (g) { g.msgStatus[key] = 'sending'; (g.msgBodies ||= {})[key] = body; opsSaveState(); updateDashboard(); } // sobrevive a la recarga (→ error reenviable)
      setTimeout(() => opsOooiSend(f(), ev, attempt + 1, body), OOOI_RETRY_MS[attempt]);
      return;
    }
    const g = f(); g.msgStatus[key] = 'error'; (g.msgBodies ||= {})[key] = body; opsSaveState(); // la tarjeta permite reintentarlo a mano (manualSend); persiste para que una recarga no deje «sending»
    log(`✗ OOOI ${ev} → ${cs}: ${e.message}`, 'err');
    recordSent(cs, g.dep, g.arr, dkey, key, 'error', body, key);
    return;
  }
  const g = f(); g.msgStatus[key] = 'sent'; (g.msgBodies ||= {})[key] = body; (g.msgSentAt ||= {})[key] = Date.now(); opsSaveState(); // persistir: si no, una recarga convierte el «sending» guardado en un «error» falso
  log(`✓ OOOI ${ev} → ${cs}`, 'ok');
  recordSent(cs, g.dep, g.arr, dkey, key, 'sent', body, key);
}
// ══════════════════════════════════════════════════════════════════
//  AUTORIZACIÓN DE RODAJE POR CPDLC — lado del OPS (5.5.2, P6)
//  El OPS decide CUÁNDO hace falta (fase LANDED, < 40 kt y a < 60 m de una calle de rodaje de OSM; sin calles, la primera muestra en
//  tierra por debajo de 40 kt) y deja el encargo en nbv_taxi_clr (almacenamiento compartido con el ACARS). El ACARS, que es quien
//  recoge la bandeja de Hoppie y lleva el MIN, lo envía y trata WILCO y UNABLE (src/app/acars/13-autorizacion.js); aquí solo se lee
//  el estado para la ficha (opsTaxiSync). Un encargo por callsign y pierna (leg = flt.firstSeen). OSM no bloquea: como mucho 8 s.
//  nbv_taxi_clr = { CS: { leg, stand, alt, route, altRoute, state, mid, t, arr, osm } }
//    state: pedida | enviada | wilco | unable | alternativa | wilco_alt | por_asignar | sin_logon | caducada · osm: puerta o ruta de OpenStreetMap
// ══════════════════════════════════════════════════════════════════
const TAXI_CLR_KEY = 'nbv_taxi_clr', TAXI_OSM_WAIT_MS = 8000, TAXI_CLR_KEEP_MS = 24 * 3600000;
function taxiClrLoad() {
  let m = null; try { m = JSON.parse(localStorage.getItem(TAXI_CLR_KEY)); } catch (e) { log(`Autorización de rodaje: registro compartido ilegible (${e.message}), se empieza de cero`, 'wrn'); }
  return m && typeof m === 'object' && !Array.isArray(m) ? m : {};
}
function taxiClrSave(m) {
  const now = Date.now();
  for (const cs of Object.keys(m)) if (!m[cs] || now - (m[cs].t || 0) > TAXI_CLR_KEEP_MS) delete m[cs];
  try { localStorage.setItem(TAXI_CLR_KEY, JSON.stringify(m)); }
  catch (e) { log(`Autorización de rodaje: no se pudo guardar el encargo (${e.message})`, 'err'); }
}

// Datos OSM del aeropuerto sin esperar más de TAXI_OSM_WAIT_MS: si Overpass tarda, se sigue con null (la descarga sigue y queda en caché)
function opsOsmFor(icao, ms = TAXI_OSM_WAIT_MS) {
  if (!icao || icao === '????') return Promise.resolve(null);
  const osm = NBV.osm.airport(icao).catch(e => { log(`OSM ${icao}: ${e.message}`, 'wrn'); return null; });
  return Promise.race([osm, new Promise(r => setTimeout(() => r(null), ms))]);
}

const taxiChecking = new Set(); // callsign|pierna con una comprobación en curso (la espera de OSM es asíncrona)
// Revisión del punto 1: respaldo por tiempo. Si OSM no casa con la posición (puerta o calle sin dibujar, desfase de escenario), tras
// TAXI_SLOW_MS en LANDED por debajo de 40 kt se pide igualmente. taxiSlowSince: callsign|pierna → inicio de la marcha lenta
const TAXI_SLOW_MS = 120000, taxiSlowSince = new Map();
async function opsTaxiCheck(flt, pos, gs) {
  if (!flt || flt.phase !== 'LANDED' || !monitorInterval) return;
  if (!/^[A-Z0-9]{4}$/.test(String(flt.arr || ''))) return; // revisión: sin aeropuerto de llegada válido no hay puerta que pedir (ni aviso en cada muestra)
  const cs = flt.callsign, leg = flt.firstSeen, k = `${cs}|${leg}`;
  if (!(gs < NBV.taxi.OFF_RWY_KT)) taxiSlowSince.delete(k); else if (!taxiSlowSince.has(k)) taxiSlowSince.set(k, Date.now());
  const slowLong = Date.now() - (taxiSlowSince.get(k) ?? Infinity) >= TAXI_SLOW_MS;
  if (taxiClrLoad()[cs]?.leg === leg || taxiChecking.has(k)) return;
  taxiChecking.add(k);
  try {
    const osm = await opsOsmFor(flt.arr);
    if (!(NBV.taxi.offRunway(osm, pos, gs) || (!osm && gs < NBV.taxi.OFF_RWY_KT) || slowLong)) return;
    const m = taxiClrLoad();
    if (m[cs]?.leg === leg) return; // otra ventana del OPS ya lo pidió mientras se esperaba a OSM
    const live = flights[cs], tgt = live && live.firstSeen === leg ? live : flt; // el escaneo pudo sustituir el objeto del vuelo
    opsAssignStand(tgt, osm);
    const stand = tgt.assignedParking;
    if (!stand) { log(`${cs}: sin puerta en ${tgt.arr}, no se pide autorización de rodaje`, 'wrn'); return; }
    const standPos = tgt.standPos || NBV.stands.locate(stand, osm);
    const alt = NBV.stands.pick(tgt.arr, tgt.aircraft, osm, { exclude: [stand], near: standPos });
    const altPos = alt && alt.lat != null ? [alt.lat, alt.lon] : null;
    const route = osm ? NBV.taxi.route(osm, pos, standPos) : [];
    const altRoute = osm && alt ? NBV.taxi.route(osm, pos, altPos) : [];
    m[cs] = { leg, stand, alt: alt ? alt.stand : null, route, altRoute, state: 'pedida', mid: null, t: Date.now(), arr: tgt.arr,
      osm: tgt.standSrc === 'osm' || route.length > 0 };
    taxiClrSave(m);
    tgt.taxiClr = { ...m[cs] };
    log(`${cs}: autorización de rodaje pedida — ${NBV.taxi.text(stand, route)}${alt ? ` (alternativa ${standRef(alt.stand)})` : ''}`, 'ops');
  } finally { taxiChecking.delete(k); }
}

// Revisión del punto 1: pierna nueva del mismo callsign → el encargo de la anterior se descarta (el ACARS no debe enviarlo)
function opsTaxiClrDrop(cs) {
  const m = taxiClrLoad();
  if (m[cs]) { delete m[cs]; taxiClrSave(m); log(`${cs}: pierna nueva, se descarta la autorización de rodaje de la anterior`, 'ops'); }
}

// 5.5.2 (P7): pierna nueva del mismo callsign → su LOGON CPDLC guardado por el ACARS (nbv_cpdlc_logons) deja de valer
const OPS_LOGONS_KEY = 'nbv_cpdlc_logons';
// Revisión: solo un LOGON anterior al aterrizaje de la pierna anterior (ON del OOOI o, sin él, su firstSeen); uno más reciente (el piloto
// ya hizo LOGON en la puerta para la nueva) se conserva
function opsCpdlcLogonClear(cs, prev = null) {
  const to = NBV.acars.to(cs).toUpperCase(), cut = prev?.oooi?.on || prev?.firstSeen || Infinity;
  try {
    const m = JSON.parse(localStorage.getItem(OPS_LOGONS_KEY) || '{}');
    if (m && typeof m === 'object' && to in m && !(m[to] >= cut)) { delete m[to]; localStorage.setItem(OPS_LOGONS_KEY, JSON.stringify(m)); log(`${cs}: pierna nueva, el LOGON CPDLC anterior ya no vale`, 'ops'); }
  } catch (e) { log(`${cs}: no se pudo invalidar el LOGON CPDLC de la pierna anterior (${e.message})`, 'wrn'); }
}

// 5.5.2 (P8): filas «TAXI CLR» del historial, una por cada CPDLC de la autorización y por cada respuesta. El OPS solo ve el estado
// final del encargo (el ACARS puede pasar por varios entre dos pasadas): de él se deducen las filas que tiene que haber y se añaden
// las que falten (clave taxi_<pierna>_<paso>, así una recarga o dos ventanas no las repiten)
function opsTaxiHistory(f, e) {
  const S = e.state, after = (...l) => l.includes(S), rows = [];
  const sent = !after('pedida', 'sin_logon', 'caducada'), unable1 = after('unable', 'alternativa', 'wilco_alt', 'por_asignar'), altSent = after('alternativa', 'wilco_alt') || (S === 'por_asignar' && !!e.alt);
  if (S === 'sin_logon') rows.push(['nologon', 'skip', 'Sin LOGON CPDLC con la estación: la autorización no se envía']);
  if (S === 'caducada') rows.push(['expired', 'skip', 'Caducada: el ACARS no la envió en 10 min']);
  if (sent) rows.push(['clr', 'sent', NBV.taxi.text(e.stand, e.route)]);
  if (S === 'wilco') rows.push(['wilco', 'wilco', 'WILCO']);
  if (unable1) rows.push(['unable1', 'unable', 'UNABLE']);
  if (altSent) rows.push(['alt', 'sent', NBV.taxi.altText(e.alt, e.altRoute)]);
  if (S === 'wilco_alt') rows.push(['wilco_alt', 'wilco', 'WILCO']);
  if (S === 'por_asignar') { if (e.alt) rows.push(['unable2', 'unable', 'UNABLE']); rows.push(['contact', 'sent', NBV.taxi.CONTACT]); }
  // Revisión: los pasos ya anotados quedan en el propio encargo (e.hist); mirando solo msgHistory, «Limpiar» los volvía a añadir
  let added = false;
  for (const [step, status, body] of rows) {
    const key = `taxi_${e.leg}_${step}`;
    if ((e.hist || []).includes(step)) continue;
    (e.hist ||= []).push(step); added = true;
    if (msgHistory.some(m => m.cs === f.callsign && m.key === key)) continue; // fila de antes de la marca
    recordSent(f.callsign, f.dep, f.arr, 'taxi', 'TAXI CLR', status, body, key);
  }
  return added;
}

// Refleja en cada vuelo el estado de su encargo (lo actualiza el ACARS). WILCO a la alternativa: la puerta del vuelo pasa a ser esa
function opsTaxiSync() {
  const m = taxiClrLoad(); let marks = false;
  for (const f of Object.values(flights)) {
    const e = m[f.callsign];
    if (!e || e.leg !== f.firstSeen) { if (f.taxiClr) f.taxiClr = null; continue; }
    f.taxiClr = { ...e };
    if (opsTaxiHistory(f, e)) marks = true;
    if (e.state === 'wilco_alt' && e.alt && f.assignedParking !== e.alt) {
      log(`${f.callsign}: acepta la puerta alternativa ${standRef(e.alt)} (antes ${standRef(f.assignedParking)})`, 'ops');
      f.assignedParking = e.alt; f.standPos = null;
    }
  }
  if (marks) { const cur = taxiClrLoad(); for (const cs of Object.keys(cur)) if (m[cs]?.hist && cur[cs]?.leg === m[cs].leg) cur[cs].hist = m[cs].hist; taxiClrSave(cur); } // relee: el ACARS pudo cambiar el estado
}
